using GraphApi.Models.VTS.VisitasGeneradas;namespace GraphApi.Services.VTS.VisitasGeneradas{    /// <summary>    /// Define las operaciones de negocio y persistencia para VisitasGeneradas.    /// </summary>    public interface IVisitasGeneradasService    {        /// <summary>        /// Obtiene la lista de VisitasGeneradas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadVisitasGeneradas>> GetVisitasGeneradas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de VisitasGeneradas con filtros opcionales.        /// </summary>        /// <param name="visitaGeneradaID">Filtro opcional para VisitaGeneradaID.</param>        /// <param name="nombreVisitante">Filtro opcional para NombreVisitante.</param>        /// <param name="usuarioVisitadoID">Filtro opcional para UsuarioVisitadoID.</param>        /// <param name="nombreVisitado">Filtro opcional para NombreVisitado.</param>        /// <param name="correoVisitado">Filtro opcional para CorreoVisitado.</param>        /// <param name="casaID">Filtro opcional para CasaID.</param>        /// <param name="direccionCasa">Filtro opcional para DireccionCasa.</param>        /// <param name="numeroExtCasa">Filtro opcional para NumeroExtCasa.</param>        /// <param name="tipoIdentificacionID">Filtro opcional para TipoIdentificacionID.</param>        /// <param name="tipoIdentificacion">Filtro opcional para TipoIdentificacion.</param>        /// <param name="numeroIdentificacion">Filtro opcional para NumeroIdentificacion.</param>        /// <param name="rutaDocumento">Filtro opcional para RutaDocumento.</param>        /// <param name="codigoQR">Filtro opcional para CodigoQR.</param>        /// <param name="fechaEmision">Filtro opcional para FechaEmision.</param>        /// <param name="fechaExpira">Filtro opcional para FechaExpira.</param>        /// <param name="bUsado">Filtro opcional para bUsado.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetVisitasGeneradasDynamic(            int? visitaGeneradaID,            string? nombreVisitante,            int? usuarioVisitadoID,            string? nombreVisitado,            string? correoVisitado,            int? casaID,            string? direccionCasa,            string? numeroExtCasa,            int? tipoIdentificacionID,            string? tipoIdentificacion,            string? numeroIdentificacion,            string? rutaDocumento,            string? codigoQR,            DateTime? fechaEmision,            DateTime? fechaExpira,            bool? bUsado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo VisitasGenerada.        /// </summary>        /// <param name="objInput">Datos para crear el VisitasGenerada.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadVisitasGeneradas> CreateVisitasGeneradas(            clCreateVisitasGeneradas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un VisitasGenerada.        /// </summary>        /// <param name="objInput">Datos para actualizar el VisitasGenerada, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadVisitasGeneradas?> UpdateVisitasGeneradas(            clUpdateVisitasGeneradas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un VisitasGenerada por su ID.        /// </summary>        /// <param name="nVisitasGeneradasID">ID del VisitasGenerada a eliminar.</param>        Task<bool> DeleteVisitasGeneradas(int nVisitasGeneradasID);    }}